import{FLIGHT_ENDPOINTS}from'./layout.js';import{flightSafeArea}from'./flight-camera.js';
const words={'boarding-camera':'편안한 시점으로 준비해요',boarding:'비행기에 오르고 있어요',seated:'앉았어요 · 준비되면 출발해요',seal:'출발을 준비해요','taxi-out':'활주로로 이동해요','takeoff-roll':'활주로를 달려요',climb:'하늘로 올라가요',cruise:'섬 사이를 날아요','awaiting-commit':'도착할 공항으로 이어가요','destination-establish':'도착할 공항을 살펴봐요','arrival-camera':'착륙 시점을 준비해요',approach:'활주로에 가까워져요','landing-roll':'활주로에 내렸어요','taxi-in':'공항에 주차해요',open:'내릴 길을 열어요',dismount:'천천히 내려요','return-camera':'산책 화면으로 돌아가요',cancelling:'원래 자리로 내려요',reopening:'내릴 길을 다시 열어요','motion-free-wait':'움직임 없이 이동 준비','motion-free-arrived':'공항에 도착했어요'};
export function readFlightSafeArea(stage){const doc=stage.ownerDocument??globalThis.document,w=stage.clientWidth,h=stage.clientHeight,r=stage.getBoundingClientRect?.()??{left:0,top:0,right:w,bottom:h},base=flightSafeArea(w,h,{warning:doc?.body?.dataset?.saveWarning==='true'}),rect=n=>n&&!n.hidden&&(n.getClientRects?.().length??1)?n.getBoundingClientRect?.():null,panel=rect(stage.querySelector?.('.flight-controls')),footer=rect(doc?.querySelector?.('footer')),top=[rect(doc?.querySelector?.('.topbar')),rect(stage.querySelector?.('.scene-tools'))].filter(Boolean);const padding={...base,top:Math.max(base.top,...top.map(p=>p.bottom-r.top+10))};if(w>h&&panel)padding.right=Math.max(base.right,r.right-panel.left+12);else if(panel)padding.top=Math.max(padding.top,panel.bottom-r.top+10);padding.bottom=Math.max(base.bottom,...[footer].filter(Boolean).map(p=>r.bottom-p.top+8));return padding;}
export function mountFlightControls({stage,controller,returnFocus=null}){const doc=stage.ownerDocument??globalThis.document,element=doc.createElement('section'),status=doc.createElement('p'),row=doc.createElement('div'),cover=doc.createElement('div'),listeners=[],previous=doc.activeElement;let alive=true,lastPhase=null;const listen=(n,t,fn,capture=false)=>{n.addEventListener(t,fn,capture);listeners.push([n,t,fn,capture]);};element.className='flight-controls';element.style.zIndex='40';element.setAttribute('role','group');element.setAttribute('aria-label','비행 이동');status.className='flight-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');row.className='flight-buttons';element.append(status,row);cover.className='flight-cover';cover.setAttribute('data-flight-cover','');cover.setAttribute('aria-hidden','true');cover.style.pointerEvents='none';cover.style.zIndex='5';cover.style.opacity='0';
 function button(name,action){const b=doc.createElement('button');b.type='button';b.setAttribute('data-flight-'+name,'');listen(b,'click',event=>{if(!alive||b.disabled||b.hidden||event.detail>1)return;action();sync();});row.append(b);return b;}
 const start=button('start',()=>controller.startDeparture()),pause=button('pause',()=>controller.snapshot()?.paused?controller.resume():controller.pause()),action=button('action',()=>controller.cancelOrSkip()),map=button('map',()=>controller.requestMap());
 function sync(){if(!alive)return;const s=controller.snapshot();element.hidden=!s||!!s.released;if(!s)return;const message=(s.paused?(s.skip||s.queuedCancel?'계속하기를 누르면 마무리해요':'잠시 멈췄어요'):words[s.phase]??'비행 이동')+' · '+(FLIGHT_ENDPOINTS[s.to]?.label??'작은 공항');if(status.textContent!==message)status.textContent=message;start.hidden=s.phase!=='seated';start.disabled=!s.ready||s.paused||s.cancelled;start.textContent=s.ready?'비행 출발':'공항 준비 중';pause.textContent=s.paused?'계속하기':'잠깐 멈춤';pause.setAttribute('aria-pressed',String(!!s.paused));action.textContent=s.departed?'바로 도착':'내려오기';action.disabled=!!s.cancelled||!!s.queuedCancel;map.textContent='지도';map.disabled=!!s.mapQueued;element.style.bottom='auto';if(s.phase==='seated'&&lastPhase!=='seated'&&(!doc.activeElement||element.contains?.(doc.activeElement)||doc.activeElement===doc.body))start.focus?.();lastPhase=s.phase;}
 listen(doc,'keydown',event=>{if(!alive||event.repeat||event.isComposing||event.ctrlKey||event.altKey||event.metaKey||event.target?.closest?.('input,textarea,select,[contenteditable="true"]'))return;if(['KeyM','Escape','KeyE'].includes(event.code)){event.preventDefault();event.stopPropagation();event.code==='KeyM'?controller.requestMap():controller.cancelOrSkip();sync();}},true);
 stage.append(cover,element);stage.setAttribute('data-flight-active','true');sync();return{element,cover,sync,setCover(value){if(alive)cover.style.opacity=String(Math.max(0,Math.min(1,Number.isFinite(value)?value:0)));},dispose(){if(!alive)return;alive=false;for(const[n,t,fn,c]of listeners)n.removeEventListener(t,fn,c);listeners.length=0;cover.remove();element.remove();stage.setAttribute('data-flight-active','false');const target=returnFocus?.()??(previous?.isConnected?previous:null)??doc.querySelector?.('#action');target?.focus?.();}};
}
